class ModelNew(nn.Module):
    """
    Transposed 3D convolution with asymmetric input and kernel sizes,
    implemented via a hand-authored PTX kernel launched through
    cutegen.ptx_runtime.PtxModule.

    Optimization applied: since all threads within a CTA share the same
    (batch, output-channel) pair and differ only in output spatial
    position, the per-output-channel weight slice (over input channels and
    kernel taps) is identical for every thread in the block. That weight
    slice is cooperatively staged into dynamic shared memory once per CTA
    (with a single `bar.sync`), and the inner accumulation loop reads the
    weight values from shared memory instead of repeatedly re-issuing
    redundant global memory loads.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Parameter container only, to match reference initialization exactly.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self._module = _get_module()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"

        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias

        x_c = x.contiguous()
        w_c = weight.contiguous()

        N, IC, D, H, Win = x_c.shape
        IC_w, OC_per_group, KD, KH, KW = w_c.shape
        assert IC_w == IC, "weight in_channels mismatch"

        sd, sh, sw = self.stride
        pd, ph, pw = self.padding
        opd, oph, opw = self.output_padding
        groups = self.groups

        OC = OC_per_group * groups

        Dout = (D - 1) * sd - 2 * pd + KD + opd
        Hout = (H - 1) * sh - 2 * ph + KH + oph
        Wout = (Win - 1) * sw - 2 * pw + KW + opw
        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid computed output size"

        y = torch.empty((N, OC, Dout, Hout, Wout), device=x_c.device, dtype=x_c.dtype)

        has_bias = 0
        bias_ptr = 0
        if bias is not None:
            bias_c = bias.contiguous()
            bias_ptr = bias_c.data_ptr()
            has_bias = 1

        threads = 256
        P_total = Dout * Hout * Wout
        grid_x = (P_total + threads - 1) // threads

        # Dynamic shared memory: per-(n, oc) weight slice covering all
        # input channels (within the group) and all kernel taps.
        IC_per_group = IC // groups
        shared_mem_bytes = IC_per_group * KD * KH * KW * 4

        stream = torch.cuda.current_stream(x_c.device).cuda_stream

        args = [
            u64(x_c.data_ptr()),
            u64(w_c.data_ptr()),
            u64(bias_ptr),
            u64(y.data_ptr()),
            i32(N), i32(IC), i32(OC),
            i32(D), i32(H), i32(Win),
            i32(KD), i32(KH), i32(KW),
            i32(sd), i32(sh), i32(sw),
            i32(pd), i32(ph), i32(pw),
            i32(Dout), i32(Hout), i32(Wout),
            i32(groups), i32(has_bias),
        ]

        self._module.launch(
            _KERNEL_NAME,
            grid=(int(grid_x), int(OC), int(N)),
            block=(int(threads), 1, 1),
            shared_mem=int(shared_mem_bytes),
            stream=stream,
            args=args,
        )

        return y

